"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1024],{89192:t=>{t.exports=JSON.parse('{"functions":[{"name":"uprightAt","desc":"Returns a CFrame at `position` that keeps the template\'s own rotation.","params":[{"name":"template","desc":"","lua_type":"BasePart"},{"name":"position","desc":"","lua_type":"Vector3"}],"returns":[{"desc":"","lua_type":"CFrame"}],"function_type":"static","source":{"line":91,"path":"src/VfxUtil.luau"}},{"name":"play","desc":"Plays a one-shot copy of `template` at `cframe`. The clone and every part inside\\nit are anchored and made non-colliding, each ParticleEmitter is played according\\nto its attributes, Lights fade to zero brightness over 0.35 seconds, and the\\nclone is destroyed once its longest emitter has finished.\\n\\n```lua\\nVfxUtil.play(effects.Slam, VfxUtil.uprightAt(effects.Slam, hitPosition))\\n```","params":[{"name":"template","desc":"","lua_type":"BasePart"},{"name":"cframe","desc":"","lua_type":"CFrame"},{"name":"parent","desc":"Defaults to `workspace`.","lua_type":"Instance?"}],"returns":[{"desc":"The playing clone.","lua_type":"BasePart"}],"function_type":"static","source":{"line":111,"path":"src/VfxUtil.luau"}},{"name":"attach","desc":"Welds a copy of `template` to `part` and enables all of its emitters, returning\\nthe stop function. Stopping switches the emitters and lights off, which lets the\\nparticles already in flight fade out on their own before the clone is cleaned up.\\nCalling the stop function more than once does nothing.\\n\\n```lua\\nlocal stop = VfxUtil.attach(effects.Aura, character.HumanoidRootPart)\\ntask.wait(5)\\nstop()\\n```","params":[{"name":"template","desc":"","lua_type":"BasePart"},{"name":"part","desc":"The part to weld the effect to.","lua_type":"BasePart"}],"returns":[{"desc":"Stops the effect and cleans it up.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":139,"path":"src/VfxUtil.luau"}}],"properties":[],"types":[],"name":"VfxUtil","desc":"Plays VFX templates: BaseParts holding ParticleEmitters, Lights and other parts.\\nEmitters are configured with attributes:\\n- `EmitCount` (number): particles to emit. Defaults to the emitter\'s `Rate`.\\n- `EmitDelay` (number): seconds to wait before starting. Defaults to 0.\\n- `EmitDuration` (number): when above 0, the emitter is enabled for this many\\n  seconds instead of emitting `EmitCount` once. Falls back to the template\\n  part\'s own `EmitDuration` attribute, then 0.","source":{"line":13,"path":"src/VfxUtil.luau"}}')}}]);